css:
.peoplestack-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.peoplestack-sim-header {
    background: linear-gradient(135deg, #2c3e50 0%, #34495e 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 16px rgba(0,0,0,0.15);
    text-align: center;
}

.peoplestack-sim-header h1 {
    font-size: 1.8rem;
    margin-bottom: 5px;
}

.peoplestack-sim-header p {
    opacity: 0.85;
    margin: 0;
    font-size: 1rem;
}

.peoplestack-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    margin-bottom: 20px;
    color: #555;
    font-weight: 600;
}

.peoplestack-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.peoplestack-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 18px 14px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #3498db;
}

.peoplestack-sim-status-card:hover {
    transform: translateY(-3px);
}

.peoplestack-card-budget { border-top-color: #2c3e50; }
.peoplestack-card-cost { border-top-color: #27ae60; }
.peoplestack-card-hire { border-top-color: #2980b9; }
.peoplestack-card-attrition { border-top-color: #8e44ad; }
.peoplestack-card-compliance { border-top-color: #16a085; }
.peoplestack-card-exs { border-top-color: #f39c12; }
.peoplestack-card-pri { border-top-color: #e74c3c; }
.peoplestack-card-resistance { border-top-color: #d35400; }

.peoplestack-sim-label {
    color: #777;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.peoplestack-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #333;
}

.peoplestack-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #2c3e50;
}

.peoplestack-sim-briefing h3 {
    margin-top: 0;
    color: #2c3e50;
    font-size: 1.1rem;
}

.peoplestack-sim-briefing-text {
    color: #555;
    line-height: 1.6;
    font-size: 0.95rem;
}

.peoplestack-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.peoplestack-sim-controls h3 {
    margin-top: 0;
    color: #2c3e50;
    font-size: 1.15rem;
    margin-bottom: 16px;
}

.peoplestack-sim-decision-group {
    margin-bottom: 16px;
}

.peoplestack-sim-decision-group label {
    display: block;
    font-weight: 600;
    color: #444;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.peoplestack-sim-decision-group select {
    width: 100%;
    padding: 8px 12px;
    border-radius: 8px;
    border: 1px solid #ddd;
    font-size: 0.9rem;
}

.peoplestack-sim-checkbox-group {
    margin-top: 14px;
    margin-bottom: 14px;
}

.peoplestack-sim-checkbox-label {
    display: block;
    padding: 10px 14px;
    background: #f8f9fa;
    border-radius: 8px;
    margin-bottom: 8px;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.2s;
}

.peoplestack-sim-checkbox-label:hover {
    background: #e9ecef;
}

.peoplestack-sim-checkbox-label input {
    margin-right: 10px;
}

.peoplestack-sim-budget-tracker {
    background: #f0f4f8;
    padding: 14px;
    border-radius: 10px;
    margin-bottom: 16px;
    text-align: center;
    font-size: 1rem;
}

.peoplestack-sim-budget-tracker strong {
    color: #27ae60;
    font-size: 1.2rem;
}

.peoplestack-sim-events {
    background: #fff5f5;
    border: 1px solid #feb2b2;
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 16px;
}

.peoplestack-sim-events h4 {
    color: #c53030;
    margin-top: 0;
    font-size: 1rem;
}

.peoplestack-sim-history {
    margin-bottom: 24px;
}

.peoplestack-sim-chart {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    margin-bottom: 24px;
    min-height: 300px;
}

@media (max-width: 768px) {
    .peoplestack-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .peoplestack-sim-header h1 {
        font-size: 1.3rem;
    }
}

