        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var composite = r.compositeScore || 0;
            var pri = r.peopleRiskIndex || 0;

            // performance and insights are translation keys, not literal text: the Open player's
            // overlay renderer looks up any lowercase_underscore value through t() automatically
            var performance = 'perf_needs_improvement';
            if (composite >= 70 && pri <= 25) performance = 'perf_excellent_balanced';
            else if (composite >= 70 && pri > 25) performance = 'perf_efficient_unsustainable';
            else if (composite >= 50 && pri <= 30) performance = 'perf_solid_foundation';
            else if (composite >= 50) performance = 'perf_good_progress_risks';

            var insights = [];
            if (r.complianceScore < 70) insights.push('insight_compliance_gaps');
            if (r.hrbpResistance > 50) insights.push('insight_hrbp_resistance');
            if (r.exScore < 55) insights.push('insight_exs_decline');
            if (pri > 40) insights.push('insight_pri_elevated');
            if (composite >= 75 && pri <= 20) insights.push('insight_outstanding_balance');
            if (insights.length === 0) insights.push('insight_solid_overall');

            return {
                compositeScore: composite,
                peopleRiskIndex: pri,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var ds = state.domainState;
            var period = state.currentPeriod;

            if (period === 1 && ds.platform === 'B') {
                return window.mySimulation.t('hint_platform_b');
            }
            if (period === 2 && ds.hrbpResistance > 60) {
                return window.mySimulation.t('hint_high_resistance');
            }
            if (period === 2 && ds.complianceScore < 70) {
                return window.mySimulation.t('hint_compliance_risk');
            }
            if (results.events && results.events.length > 0) {
                return window.mySimulation.t('hint_events_fired');
            }
            return null;
        }

